import re,json,datetime;h=open('index.html').read();db=json.loads(re.search(r'let DB=(\[\[.*?\]\]);',h,re.S)[1]);cats={};[cats.setdefault(r[2],[]).append({'nome':r[0],'un':r[1],'preco':r[3],'marca':r[4]}) for r in db];json.dump({'atualizado_em':str(datetime.date.today()),'total_produtos':len(db),'categorias':cats},open('precos.json','w'),indent=2,ensure_ascii=False);s="fetch('/precos.json').then(r=>r.json()).then(d=>{if(d.categorias){DB=[];Object.entries(d.categorias).forEach(([c,l])=>l.forEach(p=>DB.push([p.nome,p.un,c,p.preco,p.marca||''])));localStorage.setItem('mv_db',JSON.stringify(DB));render()}}).catch(()=>{});";open('index.html','w').write(h.replace('render();',s+'render();',1) if 'precos.json' not in h else h)
